#define MAXDIST 30.f
#define MAXSTEP 128
#define minDist .00001

struct Ray
{
    vec3 ro;
    vec3 rd;
};

//https://iquilezles.org/articles/distfunctions/
float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}
float sdBox( vec3 p, vec3 b )
{
  //width,height,longth
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdRoundedCylinder( vec3 p, float ra, float rb, float h )
{
  vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
  return min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb;
}

//https://iquilezles.org/articles/distfunctions/
float opU( float d1, float d2 )
{
    return min(d1,d2);
}
float opSub( float d1, float d2 )
{
    return max(-d1,d2);
}
float opIntersection( float d1, float d2 )
{
    return max(d1,d2);
}
float opXor(float d1, float d2 )
{
    return max(min(d1,d2),-max(d1,d2));
}

float opSmin( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float opSmsub( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

float opSmoothIntersection( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h);
}

vec3 opRepetition( in vec3 p, in vec3 s)
{
    vec3 q = p - s*round(p/s);
    return q;
}

float repetition_rotational( vec3 p, int n )
{
    float sp = 6.283185/float(n);
    float an = atan(p.y,p.x);
    float id = floor(an/sp);

    float a1 = sp*(id+0.0);
    float a2 = sp*(id+1.0);
    vec2 r1 = mat2(cos(a1),-sin(a1),sin(a1),cos(a1))*p.zz;
    vec2 r2 = mat2(cos(a2),-sin(a2),sin(a2),cos(a2))*p.zy;

    return opSmin( sdSphere(vec3(r1,p.z),id), sdBox(vec3(r2,p.z),vec3(id+1.0)),3. );
}


//combination
float map(in vec3 pos)
{
    //closest edge found, init as small number for a reason idk, thank you IQ
    float ce = pos.y;

    vec3 q = pos - vec3(.0,-7.,10.0);

    ce = repetition_rotational(q,int (abs(tan(iTime/2.)))+1);



    return ce;
}

//https://iquilezles.org/articles/normalsSDF/
vec3 calcNormal( in vec3 pos ){

    vec2 e = vec2(1.0,-1.0)*0.3108*0.0005;
    return normalize( e.xyy*map( pos + e.xyy ) + 
					  e.yyx*map( pos + e.yyx ) + 
					  e.yxy*map( pos + e.yxy ) + 
					  e.xxx*map( pos + e.xxx ) );

}

vec3 getColor(in vec3 rd){

    vec3 ro = vec3(0.0,3.,-8.);
    //take the dist to an edge then multiply with the normalized rd
    rd -= vec3(.0,.0,0.);
    float distToEdge = map(rd);


    for(int i = 0; i < MAXSTEP; i++){
        //ray step
        distToEdge = map(ro);
        ro += rd * distToEdge;

        if(distToEdge < minDist)
        {
            break;
        }

        if(length(ro) > MAXDIST || i-1 > MAXSTEP){
            return(vec3(.0));
        }




    }
    vec3 lightSource = vec3(0.,1.,-.5);
    float lambert = dot(calcNormal(ro),lightSource);

    return vec3(lambert+.4,lambert+.2,lambert+.6);

}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // most of this initial stuf is from https://blog.demofox.org/2020/05/25/casual-shadertoy-path-tracing-1-basic-camera-diffuse-emissive/
    vec3 screen = vec3((fragCoord/iResolution.xy) * 2.0f - 1.0f, 1.0f);
    // correct for aspect ratio
    float aspectRatio = iResolution.x / iResolution.y;
    screen.y /= aspectRatio;

    Ray ray;

    ray.rd = normalize(screen - ray.ro);

    vec3 col = getColor(ray.rd);


    // Output to screen
    fragColor = vec4(col,1.0);
}
